use std :: fs ; use std :: error :: Error ; pub fn run (config : Config) -> Result < () , Box < dyn Error > > { let contents = fs :: read_to_string (config . filename) ? ; println ! ("With text:\n{}" , contents) ; Ok (()) } pub struct Config { pub query : String , pub filename : String } impl Config { pub fn new (args : & [String]) -> Result < Config , & 'static str > { if args . len () < 3 { return Err ("u need s args") ; } let query = args [1] . clone () ; let filename = args [2] . clone () ; Ok (Config { query , filename , }) } } # [cfg (test)] mod tests { use super :: * ; # [test] fn test_config () { if let Ok (config) = Config :: new (& [String :: from ("") , String :: from ("search") , String :: from ("file") ,]) { assert_eq ! (config . query , "search" , "its search") ; } } }